class Db {
  constructor() {
    this.tasks = new Map();
    this.closed = false;
    this.nextId = 1;
  }

  insert(task) {
    const id = String(this.nextId++);
    this.tasks.set(id, { id, ...task });
    return this.tasks.get(id);
  }

  all() {
    return [...this.tasks.values()];
  }

  close() {
    this.closed = true;
  }
}

