async function withTestApp(testFn) {
  const db = new Db();
  const app = createApp(db);

  db.insert({ title: "Seed task 1" });
  db.insert({ title: "Seed task 2" });

  try {
    return await testFn(app, db);
  } finally {
    db.closed = true;
  }
}
